/* Palette: #2d1b4e (dark purple), #f9f6f0 (cream), #ffb347 (orange), #6b8cae (blue), #e07a5f (coral) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: #2d1b4e;
  color: #f9f6f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: #3d2b5e;
  border-radius: 24px;
  padding: 24px 20px;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: #ffb347;
  text-transform: uppercase;
}

.pet-area {
  width: 160px;
  height: 160px;
  background: #4a3a6e;
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 3px solid #6b8cae;
}

.pet {
  width: 100px;
  height: 100px;
  position: relative;
  image-rendering: pixelated;
  transition: transform 0.2s;
}

/* Pixel pet drawn with box-shadow */
.pet::before {
  content: '';
  position: absolute;
  left: 10px;
  top: 10px;
  width: 10px;
  height: 10px;
  background: transparent;
  box-shadow:
    /* body outline */
    0 0 0 0 #e07a5f,
    10px 0 0 0 #e07a5f,
    20px 0 0 0 #e07a5f,
    30px 0 0 0 #e07a5f,
    40px 0 0 0 #e07a5f,
    50px 0 0 0 #e07a5f,
    60px 0 0 0 #e07a5f,
    70px 0 0 0 #e07a5f,
    80px 0 0 0 #e07a5f,
    0 10px 0 0 #e07a5f,
    80px 10px 0 0 #e07a5f,
    0 20px 0 0 #e07a5f,
    80px 20px 0 0 #e07a5f,
    0 30px 0 0 #e07a5f,
    80px 30px 0 0 #e07a5f,
    0 40px 0 0 #e07a5f,
    80px 40px 0 0 #e07a5f,
    0 50px 0 0 #e07a5f,
    80px 50px 0 0 #e07a5f,
    0 60px 0 0 #e07a5f,
    80px 60px 0 0 #e07a5f,
    0 70px 0 0 #e07a5f,
    80px 70px 0 0 #e07a5f,
    0 80px 0 0 #e07a5f,
    10px 80px 0 0 #e07a5f,
    20px 80px 0 0 #e07a5f,
    30px 80px 0 0 #e07a5f,
    40px 80px 0 0 #e07a5f,
    50px 80px 0 0 #e07a5f,
    60px 80px 0 0 #e07a5f,
    70px 80px 0 0 #e07a5f,
    80px 80px 0 0 #e07a5f,
    /* body fill */
    10px 10px 0 0 #e07a5f,
    20px 10px 0 0 #e07a5f,
    30px 10px 0 0 #e07a5f,
    40px 10px 0 0 #e07a5f,
    50px 10px 0 0 #e07a5f,
    60px 10px 0 0 #e07a5f,
    70px 10px 0 0 #e07a5f,
    10px 20px 0 0 #e07a5f,
    70px 20px 0 0 #e07a5f,
    10px 30px 0 0 #e07a5f,
    70px 30px 0 0 #e07a5f,
    10px 40px 0 0 #e07a5f,
    70px 40px 0 0 #e07a5f,
    10px 50px 0 0 #e07a5f,
    70px 50px 0 0 #e07a5f,
    10px 60px 0 0 #e07a5f,
    70px 60px 0 0 #e07a5f,
    10px 70px 0 0 #e07a5f,
    20px 70px 0 0 #e07a5f,
    30px 70px 0 0 #e07a5f,
    40px 70px 0 0 #e07a5f,
    50px 70px 0 0 #e07a5f,
    60px 70px 0 0 #e07a5f,
    70px 70px 0 0 #e07a5f,
    /* eyes */
    20px 30px 0 0 #2d1b4e,
    30px 30px 0 0 #2d1b4e,
    50px 30px 0 0 #2d1b4e,
    60px 30px 0 0 #2d1b4e,
    /* mouth */
    30px 50px 0 0 #2d1b4e,
    40px 50px 0 0 #2d1b4e,
    50px 50px 0 0 #2d1b4e,
    40px 60px 0 0 #2d1b4e;
}

.mood-text {
  font-size: 1.1rem;
  font-weight: 600;
  color: #ffb347;
  text-align: center;
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: #c9b8e8;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.bar-container {
  width: 100%;
  height: 18px;
  background: #2d1b4e;
  border-radius: 9px;
  overflow: hidden;
  border: 2px solid #6b8cae;
}

.bar-fill {
  height: 100%;
  border-radius: 7px;
  transition: width 0.4s ease;
  background: #ffb347;
}

#hungerFill { background: #e07a5f; }
#happinessFill { background: #ffb347; }
#energyFill { background: #6b8cae; }

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  background: #6b8cae;
  color: #f9f6f0;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
  flex: 1;
}

button:hover {
  background: #8aa8c7;
}

button:focus-visible {
  outline: 3px solid #ffb347;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #4a6a8a;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

@media (max-width: 400px) {
  body { font-size: 16px; }
  .game-card { padding: 16px 12px; gap: 16px; }
  h1 { font-size: 1.3rem; }
  .pet-area { width: 130px; height: 130px; }
  .pet { transform: scale(0.8); }
  button { padding: 10px 12px; font-size: 0.95rem; min-width: 60px; }
}

const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

const els = {
  hungerBar: document.getElementById('hungerBar'),
  hungerFill: document.getElementById('hungerFill'),
  happinessBar: document.getElementById('happinessBar'),
  happinessFill: document.getElementById('happinessFill'),
  energyBar: document.getElementById('energyBar'),
  energyFill: document.getElementById('energyFill'),
  moodText: document.getElementById('moodText'),
  feedBtn: document.getElementById('feedBtn'),
  playBtn: document.getElementById('playBtn'),
  sleepBtn: document.getElementById('sleepBtn'),
  pet: document.getElementById('pet')
};

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  els.hungerFill.style.width = state.hunger + '%';
  els.hungerBar.setAttribute('aria-valuenow', state.hunger);
  els.happinessFill.style.width = state.happiness + '%';
  els.happinessBar.setAttribute('aria-valuenow', state.happiness);
  els.energyFill.style.width = state.energy + '%';
  els.energyBar.setAttribute('aria-valuenow', state.energy);

  els.moodText.textContent = getMood();

  els.feedBtn.disabled = state.hunger >= 100;
  els.playBtn.disabled = state.happiness >= 100 || state.energy <= 0;
  els.sleepBtn.disabled = state.energy >= 100;
}

function getMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  if (state.hunger < 20) return 'I\'m so hungry...';
  if (state.energy < 20) return 'I\'m sleepy...';
  if (state.happiness < 20) return 'I\'m sad...';
  if (avg > 80) return 'I feel amazing!';
  if (avg > 60) return 'I\'m happy!';
  if (avg > 40) return 'I\'m okay.';
  return 'I need some care...';
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy + 5);
  animatePet();
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  animatePet();
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  animatePet();
  updateUI();
}

function animatePet() {
  els.pet.style.transform = 'scale(1.1)';
  setTimeout(() => { els.pet.style.transform = 'scale(1)'; }, 200);
}

els.feedBtn.addEventListener('click', feed);
els.playBtn.addEventListener('click', play);
els.sleepBtn.addEventListener('click', sleep);

updateUI();
